import { Group, Mesh, BoxGeometry, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, Color } from 'three/webgpu';
import { uv, vec2, vec3, length, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'quote-panel-pricing';

  const inner = new Group();
  root.add(inner);

  // ---- dimensions -----------------------------------------------------
  const cardW = 2.2;
  const cardH = 1.3;
  const cardDepth = 0.09;

  // ---- edge accent frame (peeks out behind the card) -------------------
  const edgeGlow = uniform(0.15);
  const edgeGeometry = new BoxGeometry(cardW + 0.1, cardH + 0.1, 0.05);
  const edgeMaterial = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.45,
    metalness: 0.5,
  });
  edgeMaterial.emissiveNode = vec3(
    ...new Color(colors.accent).toArray()
  ).mul(edgeGlow);
  const edgeMesh = new Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.set(0, 0, -0.06);
  inner.add(edgeMesh);

  // ---- main card body (extruded box, PBR) ------------------------------
  const cardGeometry = new BoxGeometry(cardW, cardH, cardDepth);
  const cardMaterial = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.15,
    clearcoatRoughness: 0.3,
  });
  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.position.set(0, 0, 0);
  inner.add(cardMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      cardMaterial.map = tex;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- contact shadow (radial falloff plane) ---------------------------
  const shadowGeometry = new PlaneGeometry(cardW * 1.3, cardH * 0.9);
  const shadowMaterial = new MeshBasicNodeMaterial({ transparent: true });
  const shUv = uv();
  const shCenter = vec2(0.5, 0.5);
  const shDist = length(shUv.sub(shCenter));
  shadowMaterial.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMaterial.opacityNode = smoothstep(0.5, 0.0, shDist).mul(0.45);
  const shadowMesh = new Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardH * 0.68, -0.02);
  inner.add(shadowMesh);

  // ---- local lighting (rim opposite key, accent hue) -------------------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.75);
  rimLight.position.set(-2, 1.2, 2.5);
  root.add(rimLight);

  const fillLight = new DirectionalLight(new Color(colors.paper), 0.3);
  fillLight.position.set(1.5, 0.8, 2.0);
  root.add(fillLight);

  // ---- cinematic primitives --------------------------------------------
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // ---- interaction motion (hover rise-in / press-down) ------------------
  const HOVER_RISE = 0.15;
  const baseScale = { x: 1, y: 1, z: 1 };

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(inner.position, {
    y: HOVER_RISE,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  hoverTl.to(edgeGlow, {
    value: 0.9,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  const settleTl = gsap.timeline({ paused: true });

  function onHover() {
    hoverTl.play();
  }

  function onHoverOut() {
    hoverTl.reverse();
  }

  function onClick() {
    const pressTl = gsap.timeline();
    pressTl.to(inner.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
    pressTl.to(inner.scale, {
      x: 1.0, y: 1.0, z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    });
    ctx.emit('hub-pricing.select', { nodeId: config.id ?? 'quote-panel-pricing' });
  }

  function onFocus() {
    gsap.to(edgeGlow, { value: 1.1, duration: 0.3, ease: 'power2.out' });
  }

  function onBlur() {
    gsap.to(edgeGlow, { value: 0.15, duration: 0.3, ease: 'power2.out' });
  }

  root.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
    onFocus,
    onBlur,
  };

  // ---- cleanup ------------------------------------------------------
  root.userData.cleanup = function cleanup() {
    hoverTl.kill();
    settleTl.kill();
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') {
        handle.cleanup();
      }
    }
    cardGeometry.dispose();
    edgeGeometry.dispose();
    shadowGeometry.dispose();
    cardMaterial.dispose();
    edgeMaterial.dispose();
    shadowMaterial.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
    root.remove(rimLight);
    root.remove(fillLight);
  };

  return root;
}
